sys_script_include.script:
var TrainingFilter = Class.create();
TrainingFilter.prototype = {
    initialize: function() {},
    // retornar os treinamentos disponiveis 
    getAvailableTrainings: function() {
        // armazenar os treinamentos disponiveis para o user
        var scheduledTrainings = [];
        // pega o sys_id do user
        var currentUser = gs.getUserID();
        // obtem a data de hoje
        var today = new GlideDate();
        today.setValue(new GlideDateTime().getLocalDate().toString());

        // buscar os treinamentos que o usuário já tá inscrito	
        var grRegistration = new GlideRecord('x_1593191_cooknow_registration');
        // filtra pelo usuario atual e o state não é 'reproved'
        grRegistration.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4");
        grRegistration.query();

        // add os treinamentos nos quais o usuário já está inscrito
        while (grRegistration.next()) {
            scheduledTrainings.push(grRegistration.training.sys_id.toString());
        }

		// coloca os treinamentos já disponiveis
        var availableTrainings = [];
        var grTrainingSchedule = new GlideRecord("x_1593191_cooknow_training_schedule");
		// mostra só os treinamentos que ainda não aconteceram
        grTrainingSchedule.addQuery('date', '>', today); 
        grTrainingSchedule.query();

		// itera os treinamentos disponiveis, pegando o instrutor, a quantidade de vagas e a quantidade de inscritos
        while (grTrainingSchedule.next()) {
            var instructorID = grTrainingSchedule.instructor;
            var seats = grTrainingSchedule.seats;
            var enrolledCount = this.getEnrolledCount(grTrainingSchedule.getUniqueValue());

			// verifica se o user não é o instrutor, se ainda tem vagas e se o user ainda não tá inscrito no treinamento
            if (instructorID != currentUser && enrolledCount < seats && scheduledTrainings.indexOf(grTrainingSchedule.getUniqueValue()) == -1) {
                var calendarList = this.getTrainingCalendar(grTrainingSchedule.training);
                var totalEnrollments = this.getTotalEnrollments(calendarList, currentUser);

				// Limita inscrições a 3 por tipo de treinamento
                if (totalEnrollments < 3) { 
                    availableTrainings.push(grTrainingSchedule.getUniqueValue());
                }
            }
        }
		// retorna os treinamentos disponiveis
        return 'sys_idIN' + availableTrainings.join(',');
    },

	// retorna a quantidade de usuários inscritos em determinado treinamento, verificando as que o state não é 4
    getEnrolledCount: function(trainingSysId) {
        var grRegistration = new GlideRecord('x_1593191_cooknow_registration');
        grRegistration.addQuery('training', trainingSysId);
        grRegistration.addQuery('state', '!=', 4);
        grRegistration.query();
		// retorna o cont dos inscritos
        return grRegistration.getRowCount();
    },

	// retorna todos os agendamentos de um treinamento
    getTrainingCalendar: function(trainingId) {
        var calendarList = [];
        var grCalendarList = new GlideRecord("x_1593191_cooknow_training_schedule");
		// filtra os registros por treinamento
        grCalendarList.addQuery('training', trainingId);
        grCalendarList.query();

        while (grCalendarList.next()) {
            calendarList.push(grCalendarList.getUniqueValue());
        }
        return calendarList;
    },

	// retorna a qntd de treinamento do mesmo tipo que o user tá inscrito
    getTotalEnrollments: function(calendarList, userId) {
        var grRegTotalSameTraining = new GlideRecord('x_1593191_cooknow_registration');
        grRegTotalSameTraining.addEncodedQuery("opened_by=" + userId + "^trainingIN" + calendarList.join(','));
        grRegTotalSameTraining.query();
        return grRegTotalSameTraining.getRowCount();
    },

    type: 'TrainingFilter'
};
